const FILTER_OPERATORS=["equals","not-equals","contains","not-contains","gt","gte","lt","lte","before","after","is-empty","is-not-empty"];
function filterRow(database,condition,index){return `<div class="filter-clause" data-filter-index="${index}"><select id="${index?"": "filterProperty"}" data-filter-property>${database.properties.map(property=>`<option value="${escapeAttribute(property.id)}" ${condition?.propertyId===property.id?"selected":""}>${escapeHtml(property.name)}</option>`).join("")}</select><select id="${index?"":"filterOperator"}" data-filter-operator>${FILTER_OPERATORS.map(operator=>`<option value="${operator}" ${condition?.operator===operator?"selected":""}>${operator.replaceAll("-"," ")}</option>`).join("")}</select><input id="${index?"":"filterValue"}" data-filter-value value="${escapeHtml(condition?.value??"")}" placeholder="Value"><button data-remove-filter="${index}" aria-label="Remove filter">×</button></div>`;}
