function renderLinkLifecycle(container,entries,emptyText,includeBlockTarget=false){container.replaceChildren();if(!entries.length){const empty=document.createElement("p");empty.className="muted";empty.textContent=emptyText;container.append(empty);return;}for(const entry of entries){const available=entry.status==="live",recoverable=entry.status==="trashed",control=document.createElement(available||recoverable?"button":"span");control.className=`context-link${available?"":recoverable?" recovery":" unavailable"}`;control.textContent=linkEntryLabel(entry);if(available){control.type="button";control.dataset.openPage=entry.pageId;if(includeBlockTarget)control.dataset.focusBlock=entry.blockId;}else if(recoverable){control.type="button";control.dataset.revealTrashed=entry.pageId;}else control.setAttribute("aria-disabled","true");container.append(control);}}
renderContext=function(page){if(!page){renderLinkLifecycle($("#outgoingLinks"),[],"Open a page to see connections.");renderLinkLifecycle($("#backlinks"),[],"Open a page to see connections.");return;}rebuildLinks();const input={pages:workspace().pages,links:workspace().linkIndex,pageId:page.id};renderLinkLifecycle($("#outgoingLinks"),buildLinkEntries({...input,direction:"outgoing"}),"No links from this page.");renderLinkLifecycle($("#backlinks"),buildLinkEntries({...input,direction:"incoming"}),"No backlinks yet.",true);const attachments=$("#attachments"),message=document.createElement("p");message.className="muted";message.textContent="Attachments remain available through native backup/export.";attachments.replaceChildren(message);};
